import React, { useEffect, useState } from "react";
import "./login.css";

const Login = () => {
  const [formData, setFormData] = useState({
    username: "",
    password: "",
    role: "player", // Default role
  });
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  useEffect(() => {
    // Ensure dark mode class is removed when page loads
    document.body.classList.remove("dark-mode");
  }, []);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleLogin = async (event) => {
    event.preventDefault();

    const { username, password, role } = formData;

    setError("");
    setSuccess("");

    try {
      // Construct form data string for application/x-www-form-urlencoded
      const formBody = new URLSearchParams({
        username: username,
        password: password,
      }).toString();

      // Send the POST request
      const response = await fetch("http://localhost:8080/signin", {
        method: "POST",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
        },
        body: formBody, // Send form data in the body
      });

      const result = await response.json();

      if (response.ok && result.responseHeader === "OK") {
        setSuccess("ورود با موفقیت انجام شد!");

        // Save username to localStorage
        localStorage.setItem("username", username);

        // Redirect based on role
        if (role === "player") {
          window.location.href = "/player";
        } else if (role === "designer") {
          window.location.href = "/designer";
        }
      } else if (result.responseHeader === "USERNAME_NOT_EXISTS") {
        setError("نام کاربری وجود ندارد.");
      } else if (result.responseHeader === "WRONG_PASSWORD") {
        setError("رمز عبور اشتباه است.");
      } else {
        setError("خطایی رخ داده است. لطفاً دوباره تلاش کنید.");
      }
    } catch (error) {
      console.error("Error details:", error);
      setError("خطا در برقراری ارتباط با سرور رخ داده است.");
    }
  };

  return (
    <div className="main-container">
      <div className="login-box">
        <h2>ورود به سامانه سوال پیچ</h2>
        {error && <div className="error-message">{error}</div>}
        {success && <div className="success-message">{success}</div>}
        <form id="loginForm" onSubmit={handleLogin}>
          <div className="input-group">
            <label htmlFor="username">نام کاربری:</label>
            <input
              type="text"
              id="username"
              name="username"
              value={formData.username}
              onChange={handleInputChange}
              required
            />
          </div>
          <div className="input-group">
            <label htmlFor="password">رمز عبور:</label>
            <input
              type="password"
              id="password"
              name="password"
              value={formData.password}
              onChange={handleInputChange}
              required
            />
          </div>
          <div className="input-group">
            <label htmlFor="role">نقش خود را انتخاب کنید:</label>
            <select
              id="role"
              name="role"
              value={formData.role}
              onChange={handleInputChange}
              required
            >
              <option value="player">بازیکن</option>
              <option value="designer">طراح سوال</option>
            </select>
          </div>
          <button type="submit" className="submit-btn">
            ورود
          </button>
        </form>
        <div className="signup-link">
          <p>
            حساب کاربری ندارید؟ <a href="/signup">ثبت‌نام کنید</a>
          </p>
        </div>
        {/* Dark mode toggle button */}
        <button
          id="dark-mode-toggle"
          className="dark-mode-btn"
          onClick={() => document.body.classList.toggle("dark-mode")}
        >
          <span id="icon">🌞</span>
        </button>
      </div>
    </div>
  );
};

export default Login;
